using System.Text.Json;using Microsoft.Extensions.Options;using TradingSystem.Dashboard.Contracts;using TradingSystem.JobOrchestration;using TradingSystem.Jobs.Worker.Execution;
namespace TradingSystem.Jobs.Worker.Workers;
public sealed class BacktestingJobWorker(IDashboardJobQueue queue, BacktestExecutionService executor, IOptions<JobWorkerOptions> options, ILogger<BacktestingJobWorker> logger):BackgroundService
{
 protected override async Task ExecuteAsync(CancellationToken stoppingToken){var o = options.Value;if(!o.Enabled)return;var worker = $"backtest:{Environment.MachineName}:{Guid.NewGuid():N}";using var timer = new PeriodicTimer(TimeSpan.FromSeconds(Math.Max(1, o.PollSeconds)));do{var jobs = await queue.ClaimAsync("Backtest", worker, o.BatchSize, TimeSpan.FromMinutes(o.ProcessingTimeoutMinutes), stoppingToken);foreach(var job in jobs)await Process(job, o, stoppingToken);}while(await timer.WaitForNextTickAsync(stoppingToken));}
 private async Task Process(DashboardJob job, JobWorkerOptions o, CancellationToken ct){try{await queue.ReportProgressAsync(job.JobId, 5, "Loading historical data", ct);var request = JsonSerializer.Deserialize<BacktestRequest>(job.RequestJson, new JsonSerializerOptions(JsonSerializerDefaults.Web))??throw new InvalidOperationException("Invalid backtest request.");var run = await executor.ExecuteAsync(request, o.Interval, ct);await queue.CompleteAsync(job.JobId, run, ct);}catch(Exception ex){logger.LogError(ex, "Backtest job {JobId} failed", job.JobId);await queue.FailAsync(job.JobId, ex.Message, o.MaximumAttempts, TimeSpan.FromSeconds(Math.Pow(2, job.AttemptCount)), ct);}}
}
